/*
 * ==============================================================================
 * Hardware I/O Ports & Definitions for PC Speaker Audio
 * ==============================================================================
 */

/*
 * The x86 PC speaker sound is generated by Channel 2 of the 8254 Programmable
 * Interval Timer (PIT). The timer output gates an audio pulse sent to the speaker cone.
 */
#define PIT_CHANNEL2_DATA_PORT  0x42  /* Port 0x42: PIT Channel 2 counter divisor */
#define PIT_COMMAND_PORT        0x43  /* Port 0x43: PIT Mode/Command Register */
#define SYSTEM_CONTROL_PORT_B   0x61  /* Port 0x61: System Control Port B (Speaker Gate) */

/*
 * PIT Channel 2 Mode 3 Command Byte:
 * Binary 10 11 011 0 = 0xB6:
 *   Bits 7-6 = 10:  Channel 2 (connected to PC speaker logic)
 *   Bits 5-4 = 11:  Access mode: lobyte then hibyte
 *   Bits 3-1 = 011: Mode 3 (Square wave generator for audio tones)
 *   Bit 0    = 0:   16-bit binary counter mode
 */
#define PIT_CHANNEL2_SQUARE_WAVE 0xB6

/*
 * Port 0x61 Speaker Control Bits:
 * Bit 0: Connects PIT Channel 2 timer output to speaker gate logic.
 * Bit 1: Enables physical speaker output line drive.
 * Both bits must be set (0x03) to produce audible sound.
 */
#define SPEAKER_GATE_BIT        (1 << 0)
#define SPEAKER_DATA_BIT        (1 << 1)
#define SPEAKER_ENABLE_MASK     (SPEAKER_GATE_BIT | SPEAKER_DATA_BIT)

