/*
 * ==============================================================================
 * PC Speaker Driver Helpers
 * ==============================================================================
 */

/*
 * speaker_play_tone:
 * Generates an audio tone by configuring PIT Channel 2 in square-wave mode
 * and unmasking the speaker drive bits on Port 0x61.
 *
 * Parameters:
 *   freq_hz - Pitch frequency in Hertz. If 0, tone is silenced.
 */
void speaker_play_tone(uint32_t freq_hz) {
    if (freq_hz == 0) {
        speaker_stop();
        return;
    }

    /* PIT base oscillator is 1,193,182 Hz.
     * Divisor = 1193182 / freq_hz.
     */
    uint32_t divisor = 1193182 / freq_hz;
    if (divisor > 65535) divisor = 65535;
    if (divisor < 1)     divisor = 1;

    /* Program PIT Channel 2 in square wave mode (0xB6) */
    outb(PIT_COMMAND_PORT, PIT_CHANNEL2_SQUARE_WAVE);

    /* Send 16-bit divisor low byte first, then high byte */
    outb(PIT_CHANNEL2_DATA_PORT, (uint8_t)(divisor & 0xFF));
    outb(PIT_CHANNEL2_DATA_PORT, (uint8_t)((divisor >> 8) & 0xFF));

    /* Enable PC speaker by setting bits 0 and 1 of Port 0x61 */
    uint8_t cur = inb(SYSTEM_CONTROL_PORT_B);
    if ((cur & SPEAKER_ENABLE_MASK) != SPEAKER_ENABLE_MASK) {
        outb(SYSTEM_CONTROL_PORT_B, (uint8_t)(cur | SPEAKER_ENABLE_MASK));
    }
}

/*
 * speaker_stop:
 * Silences the PC speaker by clearing bits 0 and 1 of Port 0x61.
 */
void speaker_stop(void) {
    uint8_t cur = inb(SYSTEM_CONTROL_PORT_B);
    outb(SYSTEM_CONTROL_PORT_B, (uint8_t)(cur & ~SPEAKER_ENABLE_MASK));
}

/*
 * ==============================================================================
 * Formatting & UI Rendering Routines
 * ==============================================================================
 */

/* Formats elapsed and total track duration into MM:SS / MM:SS string */
static void format_time_string(char* out_buf, uint32_t elapsed_sec, uint32_t total_sec) {
    uint32_t e_min = elapsed_sec / 60;
    uint32_t e_sec = elapsed_sec % 60;
    uint32_t t_min = total_sec / 60;
    uint32_t t_sec = total_sec % 60;

    out_buf[0]  = (char)('0' + ((e_min / 10) % 10));
    out_buf[1]  = (char)('0' + (e_min % 10));
    out_buf[2]  = ':';
    out_buf[3]  = (char)('0' + ((e_sec / 10) % 10));
    out_buf[4]  = (char)('0' + (e_sec % 10));
    out_buf[5]  = ' ';
    out_buf[6]  = '/';
    out_buf[7]  = ' ';
    out_buf[8]  = (char)('0' + ((t_min / 10) % 10));
    out_buf[9]  = (char)('0' + (t_min % 10));
    out_buf[10] = ':';
    out_buf[11] = (char)('0' + ((t_sec / 10) % 10));
    out_buf[12] = (char)('0' + (t_sec % 10));
    out_buf[13] = '\0';
}

/*
 * render_track_info:
 * Renders the top LCD-style Track Information Card with Title, Artist,
 * Time Readout, Playback Status Badge, and Bitrate indicator.
 */
static void render_track_info(window_t* win) {
    /* 1. Background dark LCD display surface */
    window_fill_rect(win, INFO_CARD_X, INFO_CARD_Y, INFO_CARD_W, INFO_CARD_H, 0x000A0D14);
    window_draw_rect(win, INFO_CARD_X, INFO_CARD_Y, INFO_CARD_W, INFO_CARD_H, 0x00283446);

    /* 2. Track Number & Title */
    char title_buf[48];
    title_buf[0] = (char)('1' + s_current_track);
    title_buf[1] = '.';
    title_buf[2] = ' ';
    int idx = 3;
    const char* t = s_tracks[s_current_track].title;
    while (*t && idx < 42) {
        title_buf[idx++] = *t++;
    }
    title_buf[idx] = '\0';
    window_draw_string(win, INFO_CARD_X + 10, INFO_CARD_Y + 6, title_buf, 0x0040F0D0, 0x000A0D14, false);

    /* 3. Composer / Artist */
    char artist_buf[48];
    strcpy(artist_buf, "Artist: ");
    strcat(artist_buf, s_tracks[s_current_track].artist);
    window_draw_string(win, INFO_CARD_X + 10, INFO_CARD_Y + 24, artist_buf, 0x008CA0C0, 0x000A0D14, false);

    /* 4. Elapsed Time / Total Time */
    uint32_t elapsed_sec = s_track_ticks_elapsed / 100;
    if (elapsed_sec > s_tracks[s_current_track].total_sec) {
        elapsed_sec = s_tracks[s_current_track].total_sec;
    }
    char time_str[24];
    format_time_string(time_str, elapsed_sec, s_tracks[s_current_track].total_sec);
    window_draw_string(win, INFO_CARD_X + 10, INFO_CARD_Y + 44, time_str, 0x0033FF66, 0x000A0D14, false);

    /* 5. Playback Status Badge */
    const char* status_badge = "[STOPPED]";
    uint32_t status_color    = 0x008899A6;

    if (s_is_muted) {
        status_badge = "[MUTED]  ";
        status_color = 0x00FF4040;
    } else if (s_is_playing) {
        if (s_is_paused) {
            status_badge = "[PAUSED] ";
            status_color = 0x00F0D020;
        } else {
            status_badge = "[PLAYING]";
            status_color = 0x0020E040;
        }
    }
    window_draw_string(win, INFO_CARD_X + 146, INFO_CARD_Y + 44, status_badge, status_color, 0x000A0D14, false);

    /* 6. Audio Format & Bitrate */
    window_draw_string(win, INFO_CARD_X + 232, INFO_CARD_Y + 44, s_tracks[s_current_track].bitrate,
                       0x00FFB020, 0x000A0D14, false);
}

/*
 * render_equalizer:
 * Renders the animated 8-band Frequency Spectrum Visualizer with LED segments,
 * peak hold indicators with fall-off animation, and frequency band markings.
 */
static void render_equalizer(window_t* win) {
    /* 1. Equalizer outer container & bezel frame */
    window_fill_rect(win, EQ_BOX_X, EQ_BOX_Y, EQ_BOX_W, EQ_BOX_H, 0x000E1218);
    window_draw_rect(win, EQ_BOX_X, EQ_BOX_Y, EQ_BOX_W, EQ_BOX_H, 0x00243040);

    /* 2. Oscilloscope / Spectrum Analyzer subtle horizontal grid lines */
    for (int gy = EQ_BOX_Y + 10; gy < EQ_BOX_Y + 50; gy += 10) {
        for (int gx = EQ_BOX_X + 4; gx < EQ_BOX_X + EQ_BOX_W - 4; gx += 4) {
            window_putpixel(win, gx, gy, 0x00161E28);
        }
    }

    /* 3. Center the 8 equalizer bars inside the box */
    int total_bars_w = NUM_EQ_BANDS * EQ_BAR_W + (NUM_EQ_BANDS - 1) * EQ_BAR_GAP;
    int bar_start_x  = EQ_BOX_X + (EQ_BOX_W - total_bars_w) / 2;
    int base_y       = EQ_BOX_Y + 52; /* Bottom baseline of bars */

    for (int b = 0; b < NUM_EQ_BANDS; b++) {
        int bx = bar_start_x + b * (EQ_BAR_W + EQ_BAR_GAP);

        /* Draw 11 vertical LED segments from bottom to top */
        for (int seg = 0; seg < EQ_SEGMENTS_COUNT; seg++) {
            int seg_y = base_y - (seg + 1) * (EQ_SEGMENT_H + EQ_SEGMENT_GAP);
            int seg_threshold = (seg + 1) * (EQ_BAR_MAX_H / EQ_SEGMENTS_COUNT);

            bool is_lit = (s_bar_height[b] >= seg_threshold);
            uint32_t seg_col;

            /* Segment colors: Green base, Amber mid-range, Red peak */
            if (seg < 6) {
                seg_col = is_lit ? EQ_COLOR_BASE_LIT : EQ_COLOR_BASE_DIM;
            } else if (seg < 9) {
                seg_col = is_lit ? EQ_COLOR_MID_LIT : EQ_COLOR_MID_DIM;
            } else {
                seg_col = is_lit ? EQ_COLOR_PEAK_LIT : EQ_COLOR_PEAK_DIM;
            }

            window_fill_rect(win, bx, seg_y, EQ_BAR_W, EQ_SEGMENT_H, seg_col);
        }

        /* 4. Draw Peak Hold Line with fall-off physics */
        if (s_peak_height[b] > 0) {
            int peak_seg = (s_peak_height[b] * EQ_SEGMENTS_COUNT) / EQ_BAR_MAX_H;
            if (peak_seg >= EQ_SEGMENTS_COUNT) peak_seg = EQ_SEGMENTS_COUNT - 1;
            int peak_y = base_y - (peak_seg + 1) * (EQ_SEGMENT_H + EQ_SEGMENT_GAP);
            window_fill_rect(win, bx, peak_y, EQ_BAR_W, 2, EQ_COLOR_PEAK_CAP);
        }

        /* 5. Frequency Band Label below each bar */
        int lbl_len = (int)strlen(s_eq_labels[b]);
        int lbl_x   = bx + (EQ_BAR_W - lbl_len * 8) / 2;
        window_draw_string(win, lbl_x, base_y + 2, s_eq_labels[b], 0x00557088, 0x000E1218, false);
    }
}

/*
 * render_playlist:
 * Renders the track playlist container with highlighted currently playing track
 * and duration markings.
 */
static void render_playlist(window_t* win) {
    /* 1. Outer box background & border */
    window_fill_rect(win, PLAYLIST_BOX_X, PLAYLIST_BOX_Y, PLAYLIST_BOX_W, PLAYLIST_BOX_H, 0x000B0E14);
    window_draw_rect(win, PLAYLIST_BOX_X, PLAYLIST_BOX_Y, PLAYLIST_BOX_W, PLAYLIST_BOX_H, 0x00243040);

    /* 2. Header banner */
    window_fill_rect(win, PLAYLIST_BOX_X + 1, PLAYLIST_BOX_Y + 1, PLAYLIST_BOX_W - 2, PLAYLIST_HEADER_H, 0x001B2432);
    window_draw_string(win, PLAYLIST_BOX_X + 8, PLAYLIST_BOX_Y + 2,
                       "CHIPTUNE PLAYLIST (Click track to select & play):",
                       0x007898B4, 0x001B2432, false);

    /* 3. Render 4 track rows */
    int start_y = PLAYLIST_BOX_Y + PLAYLIST_HEADER_H + 2;

    for (int i = 0; i < TRACK_COUNT; i++) {
        int ry = start_y + i * PLAYLIST_ROW_H;
        bool is_active = (i == s_current_track);

        uint32_t row_bg   = is_active ? 0x001C3C68 : ((i % 2 == 0) ? 0x000F131C : 0x000B0E14);
        uint32_t text_col = is_active ? 0x0060E0FF : 0x00B0C0D0;

        window_fill_rect(win, PLAYLIST_BOX_X + 2, ry, PLAYLIST_BOX_W - 4, PLAYLIST_ROW_H - 1, row_bg);

        if (is_active) {
            window_draw_rect(win, PLAYLIST_BOX_X + 2, ry, PLAYLIST_BOX_W - 4, PLAYLIST_ROW_H - 1, 0x003A70B0);
        }

        /* Format track title row: e.g. "> 1. Super Mario Bros - Overworld" */
        char row_str[48];
        row_str[0] = is_active ? '>' : ' ';
        row_str[1] = ' ';
        row_str[2] = (char)('1' + i);
        row_str[3] = '.';
        row_str[4] = ' ';

        int idx = 5;
        const char* t = s_tracks[i].title;
        while (*t && idx < 36) {
            row_str[idx++] = *t++;
        }
        row_str[idx] = '\0';

        window_draw_string(win, PLAYLIST_BOX_X + 6, ry + 1, row_str, text_col, row_bg, false);

        /* Format duration e.g. "00:45" at right edge */
        char dur_str[8];
        uint32_t m = s_tracks[i].total_sec / 60;
        uint32_t s = s_tracks[i].total_sec % 60;
        dur_str[0] = (char)('0' + ((m / 10) % 10));
        dur_str[1] = (char)('0' + (m % 10));
        dur_str[2] = ':';
        dur_str[3] = (char)('0' + ((s / 10) % 10));
        dur_str[4] = (char)('0' + (s % 10));
        dur_str[5] = '\0';

        window_draw_string(win, PLAYLIST_BOX_X + PLAYLIST_BOX_W - 54, ry + 1,
                           dur_str, is_active ? 0x00FFFFFF : 0x00688098, row_bg, false);
    }
}

/*
 * player_redraw_all:
 * Completely redraws the Media Player client surface and flushes to display.
 */
static void player_redraw_all(window_t* win) {
    if (!win) return;

    /* Base dark charcoal background */
    window_clear_client(win, 0x00141820);

    /* Render visual modules */
    render_track_info(win);
    render_equalizer(win);
    render_playlist(win);

    /* Render control toolbar buttons */
    widget_render_all(win);

    /* Invalidate entire window client rect to update screen buffer */
    wm_invalidate_rect(win->client_x, win->client_y, win->client_width, win->client_height);
}

/*
 * player_redraw_dynamic:
 * Fast partial redraw of dynamic elements (Track Info and Equalizer)
 * during playback animation ticks to minimize memory bus overhead.
 */
static void player_redraw_dynamic(window_t* win) {
    if (!win) return;

    render_track_info(win);
    render_equalizer(win);

    /* Invalidate only the top portion covering Track Info and Equalizer */
    wm_invalidate_rect(win->client_x + INFO_CARD_X,
                       win->client_y + INFO_CARD_Y,
                       INFO_CARD_W,
                       (EQ_BOX_Y + EQ_BOX_H) - INFO_CARD_Y);
}

/*
 * ==============================================================================
 * Playback Control Commands
 * ==============================================================================
 */

static void player_play(void) {
    if (s_is_paused) {
        s_is_paused = false;
    } else {
        s_is_playing = true;
        s_is_paused  = false;
    }

    if (!s_is_muted) {
        uint16_t freq = s_tracks[s_current_track].notes[s_current_note_idx].freq;
        if (freq != NOTE_REST) {
            speaker_play_tone(freq);
        } else {
            speaker_stop();
        }
    }

    player_redraw_all(s_player_win);
}

static void player_pause(void) {
    if (!s_is_playing) return;

    s_is_paused = !s_is_paused;
    if (s_is_paused) {
        speaker_stop();
    } else {
        if (!s_is_muted) {
            uint16_t freq = s_tracks[s_current_track].notes[s_current_note_idx].freq;
            if (freq != NOTE_REST) {
                speaker_play_tone(freq);
            }
        }
    }

    player_redraw_all(s_player_win);
}

static void player_stop(void) {
    s_is_playing = false;
    s_is_paused  = false;
    speaker_stop();

    s_current_note_idx    = 0;
    s_note_ticks_elapsed  = 0;
    s_track_ticks_elapsed = 0;

    /* Drop all equalizer bars and peaks to baseline */
    for (int b = 0; b < NUM_EQ_BANDS; b++) {
        s_bar_height[b]  = 0;
        s_peak_height[b] = 0;
        s_peak_hold[b]   = 0;
    }

    player_redraw_all(s_player_win);
}

static void player_prev(void) {
    if (s_current_track > 0) {
        s_current_track--;
    } else {
        s_current_track = TRACK_COUNT - 1;
    }

    s_current_note_idx    = 0;
    s_note_ticks_elapsed  = 0;
    s_track_ticks_elapsed = 0;
    s_is_playing          = true;
    s_is_paused           = false;

    if (!s_is_muted) {
        uint16_t freq = s_tracks[s_current_track].notes[0].freq;
        if (freq != NOTE_REST) {
            speaker_play_tone(freq);
        } else {
            speaker_stop();
        }
    }

    player_redraw_all(s_player_win);
}

static void player_next(void) {
    s_current_track = (s_current_track + 1) % TRACK_COUNT;

    s_current_note_idx    = 0;
    s_note_ticks_elapsed  = 0;
    s_track_ticks_elapsed = 0;
    s_is_playing          = true;
    s_is_paused           = false;

    if (!s_is_muted) {
        uint16_t freq = s_tracks[s_current_track].notes[0].freq;
        if (freq != NOTE_REST) {
            speaker_play_tone(freq);
        } else {
            speaker_stop();
        }
    }

    player_redraw_all(s_player_win);
}

static void player_toggle_mute(void) {
    s_is_muted = !s_is_muted;

    if (s_is_muted) {
        speaker_stop();
        if (s_btn_mute) {
            widget_set_text(s_btn_mute, "Unmute");
        }
    } else {
        if (s_btn_mute) {
            widget_set_text(s_btn_mute, "Mute");
        }
        if (s_is_playing && !s_is_paused) {
            uint16_t freq = s_tracks[s_current_track].notes[s_current_note_idx].freq;
            if (freq != NOTE_REST) {
                speaker_play_tone(freq);
            }
        }
    }

    player_redraw_all(s_player_win);
}

/*
 * ==============================================================================
 * Toolbar Widget Callbacks
 * ==============================================================================
 */
static void on_btn_prev_click(widget_t* w, void* ud) {
    (void)w; (void)ud;
    player_prev();
}

static void on_btn_play_click(widget_t* w, void* ud) {
    (void)w; (void)ud;
    player_play();
}

static void on_btn_pause_click(widget_t* w, void* ud) {
    (void)w; (void)ud;
    player_pause();
}

static void on_btn_stop_click(widget_t* w, void* ud) {
    (void)w; (void)ud;
    player_stop();
}

static void on_btn_next_click(widget_t* w, void* ud) {
    (void)w; (void)ud;
    player_next();
}

static void on_btn_mute_click(widget_t* w, void* ud) {
    (void)w; (void)ud;
    player_toggle_mute();
}

/*
 * ==============================================================================
 * Window Event Handlers
 * ==============================================================================
 */

/*
 * on_player_click:
 * Handles mouse clicks inside the window client canvas. Detects clicks on
 * playlist rows to immediately select and play the targeted track.
 */
static void on_player_click(window_t* win, int rx, int ry) {
    (void)win;

    int start_y = PLAYLIST_BOX_Y + PLAYLIST_HEADER_H + 2;
    int end_y   = start_y + TRACK_COUNT * PLAYLIST_ROW_H;

    if (rx >= PLAYLIST_BOX_X && rx <= PLAYLIST_BOX_X + PLAYLIST_BOX_W &&
        ry >= start_y && ry < end_y) {
        int clicked_track = (ry - start_y) / PLAYLIST_ROW_H;
        if (clicked_track >= 0 && clicked_track < TRACK_COUNT) {
            s_current_track       = clicked_track;
            s_current_note_idx    = 0;
            s_note_ticks_elapsed  = 0;
            s_track_ticks_elapsed = 0;
            s_is_playing          = true;
            s_is_paused           = false;

            if (!s_is_muted) {
                uint16_t freq = s_tracks[s_current_track].notes[0].freq;
                if (freq != NOTE_REST) {
                    speaker_play_tone(freq);
                } else {
                    speaker_stop();
                }
            }

            player_redraw_all(s_player_win);
        }
    }
}

/*
 * on_player_key:
 * Routes keyboard input to media player actions for high-efficiency hotkeys.
 */
static void on_player_key(window_t* win, char c) {
    (void)win;

    switch (c) {
        case ' ':
            /* Spacebar toggles Play / Pause */
            player_pause();
            break;
        case 's':
        case 'S':
            /* S key stops playback */
            player_stop();
            break;
        case 'p':
        case 'P':
        case '<':
            /* P or '<' jumps to previous track */
            player_prev();
            break;
        case 'n':
        case 'N':
        case '>':
            /* N or '>' jumps to next track */
            player_next();
            break;
        case 'm':
        case 'M':
            /* M key toggles Mute */
            player_toggle_mute();
            break;
        case '1':
        case '2':
        case '3':
        case '4': {
            /* Number keys 1-4 jump directly to playlist items */
            int track_idx = c - '1';
            if (track_idx < TRACK_COUNT) {
                s_current_track       = track_idx;
                s_current_note_idx    = 0;
                s_note_ticks_elapsed  = 0;
                s_track_ticks_elapsed = 0;
                s_is_playing          = true;
                s_is_paused           = false;

                if (!s_is_muted) {
                    uint16_t freq = s_tracks[s_current_track].notes[0].freq;
                    if (freq != NOTE_REST) {
                        speaker_play_tone(freq);
                    } else {
                        speaker_stop();
                    }
                }
                player_redraw_all(s_player_win);
            }
            break;
        }
        default:
            break;
    }
}

/*
 * on_player_close:
 * Cleans up hardware audio output and resets window handles on window close.
 */
static void on_player_close(window_t* win) {
    /* 1. Silence PC speaker immediately to prevent stuck buzzer tones */
    speaker_stop();
    s_is_playing = false;
    s_is_paused  = false;

    /* 2. Reset equalizer bars and peaks */
    for (int b = 0; b < NUM_EQ_BANDS; b++) {
        s_bar_height[b]  = 0;
        s_peak_height[b] = 0;
        s_peak_hold[b]   = 0;
    }

    /* 3. Nullify button handles */
    s_btn_prev  = NULL;
    s_btn_play  = NULL;
    s_btn_pause = NULL;
    s_btn_stop  = NULL;
    s_btn_next  = NULL;
    s_btn_mute  = NULL;

    /* 4. Remove and destroy window */
    wm_remove_window(win);
    s_player_win = NULL;

    serial_writestring("[PLAYER] Media Player window closed.\n");
}

/*
 * ==============================================================================
 * Public API
 * ==============================================================================
 */

/*
 * player_app_create:
 * Creates and initializes the Media Player window and widgets at (x, y).
 */
window_t* player_app_create(int32_t x, int32_t y) {
    if (s_player_win) {
        wm_bring_to_front(s_player_win);
        return s_player_win;
    }

    s_player_win = window_create(x, y, PLAYER_WIN_WIDTH, PLAYER_WIN_HEIGHT,
                                 "Media Player - Chiptune Audio",
                                 WINDOW_FLAG_VISIBLE | WINDOW_FLAG_MOVABLE);
    if (!s_player_win) {
        return NULL;
    }

    s_player_win->bg_color = 0x00141820;
    s_player_win->on_close = on_player_close;
    s_player_win->on_click = on_player_click;
    s_player_win->on_key   = on_player_key;

    /* Create controls toolbar buttons */
    s_btn_prev  = widget_create_button(12,  CTRL_Y, 60, CTRL_H, "|< Prev", on_btn_prev_click,  NULL);
    s_btn_play  = widget_create_button(78,  CTRL_Y, 58, CTRL_H, "Play >",  on_btn_play_click,  NULL);
    s_btn_pause = widget_create_button(142, CTRL_Y, 62, CTRL_H, "Pause ||",on_btn_pause_click, NULL);
    s_btn_stop  = widget_create_button(210, CTRL_Y, 58, CTRL_H, "Stop []", on_btn_stop_click,  NULL);
    s_btn_next  = widget_create_button(274, CTRL_Y, 60, CTRL_H, "Next >|", on_btn_next_click,  NULL);
    s_btn_mute  = widget_create_button(340, CTRL_Y, 64, CTRL_H, "Mute",    on_btn_mute_click,  NULL);

    widget_add_to_window(s_player_win, s_btn_prev);
    widget_add_to_window(s_player_win, s_btn_play);
    widget_add_to_window(s_player_win, s_btn_pause);
    widget_add_to_window(s_player_win, s_btn_stop);
    widget_add_to_window(s_player_win, s_btn_next);
    widget_add_to_window(s_player_win, s_btn_mute);

    wm_add_window(s_player_win);

    /* Render initial UI */
    player_redraw_all(s_player_win);

    serial_writestring("[PLAYER] Media Player - Chiptune Audio initialized.\n");
    return s_player_win;
}

/*
 * app_player_open:
 * Opens or focuses the Media Player application window at default coordinates.
 */
void app_player_open(void) {
    if (s_player_win) {
        wm_bring_to_front(s_player_win);
        return;
    }
    player_app_create(140, 90);
}

/*
 * player_tick:
 * Periodic tick handler. Advances music note synthesis, handles note releases/rests,
 * updates peak fall-off equalizer animations, and refreshes the display.
 */
void player_tick(void) {
    /* If window is closed and playback is inactive, return immediately */
    if (!s_player_win && !s_is_playing) {
        return;
    }

    uint32_t now = timer_get_ticks();
    if (s_last_tick_time == 0) {
        s_last_tick_time = now;
        return;
    }

    uint32_t delta_ticks = now - s_last_tick_time;
    if (delta_ticks == 0) {
        return;
    }
    s_last_tick_time = now;

    /* Clamp delta_ticks to avoid skips during sudden system pauses */
    if (delta_ticks > 20) {
        delta_ticks = 20;
    }

    /* 1. Advance Musical Timeline */
    if (s_is_playing && !s_is_paused) {
        s_note_ticks_elapsed  += delta_ticks;
        s_track_ticks_elapsed += delta_ticks;

        uint32_t max_track_ticks = s_tracks[s_current_track].total_sec * 100;
        if (s_track_ticks_elapsed >= max_track_ticks) {
            s_track_ticks_elapsed = 0;
        }

        const track_t* cur_track = &s_tracks[s_current_track];
        const note_t*  cur_note  = &cur_track->notes[s_current_note_idx];

        /* Transition to next note when current note duration expires */
        if (s_note_ticks_elapsed >= cur_note->duration) {
            s_note_ticks_elapsed = 0;
            s_current_note_idx++;

            /* Loop track continuously */
            if (s_current_note_idx >= cur_track->note_count) {
                s_current_note_idx = 0;
            }

            cur_note = &cur_track->notes[s_current_note_idx];

            if (!s_is_muted) {
                if (cur_note->freq == NOTE_REST) {
                    speaker_stop();
                } else {
                    speaker_play_tone(cur_note->freq);
                }
            } else {
                speaker_stop();
            }
        } else {
            /* Note release articulation: brief 2-tick silence separates repeated notes */
            if (cur_note->duration > 4 && s_note_ticks_elapsed >= (uint32_t)(cur_note->duration - 2)) {
                speaker_stop();
            }
        }
    } else {
        speaker_stop();
    }

    /* 2. Frequency Spectrum Visualizer Animation */
    if (s_is_playing && !s_is_paused) {
        uint16_t freq = s_tracks[s_current_track].notes[s_current_note_idx].freq;

        if (freq > 0) {
            /* Determine dominant frequency band (0 to 7) */
            int primary_band = 0;
            if (freq < 220)       primary_band = 0;
            else if (freq < 330)  primary_band = 1;
            else if (freq < 440)  primary_band = 2;
            else if (freq < 587)  primary_band = 3;
            else if (freq < 784)  primary_band = 4;
            else if (freq < 1047) primary_band = 5;
            else if (freq < 1500) primary_band = 6;
            else                  primary_band = 7;

            /* Synthesize dynamic frequency bar heights with rhythmic flutter */
            for (int b = 0; b < NUM_EQ_BANDS; b++) {
                int target = 0;
                if (b == primary_band) {
                    target = 34 + (int)((now + b) % 9);
                } else if (b == primary_band - 1 || b == primary_band + 1) {
                    target = 22 + (int)((now * 3 + b) % 9);
                } else if (b == ((primary_band + 2) % NUM_EQ_BANDS)) {
                    target = 16 + (int)((now * 5 + b) % 7);
                } else {
                    target = 6 + (int)((now + b * 2) % 6);
                }

                if (target > EQ_BAR_MAX_H) target = EQ_BAR_MAX_H;

                /* Fast attack, smooth decay */
                if (s_bar_height[b] < target) {
                    s_bar_height[b] += 6;
                    if (s_bar_height[b] > target) s_bar_height[b] = target;
                } else {
                    s_bar_height[b] -= 2;
                    if (s_bar_height[b] < 0) s_bar_height[b] = 0;
                }
            }
        } else {
            /* Silence: decay all bars */
            for (int b = 0; b < NUM_EQ_BANDS; b++) {
                s_bar_height[b] -= 3;
                if (s_bar_height[b] < 0) s_bar_height[b] = 0;
            }
        }
    } else {
        /* Inactive or paused: decay all bars to 0 */
        for (int b = 0; b < NUM_EQ_BANDS; b++) {
            s_bar_height[b] -= 3;
            if (s_bar_height[b] < 0) s_bar_height[b] = 0;
        }
    }

    /* 3. Peak Hold & Fall-off Physics */
    for (int b = 0; b < NUM_EQ_BANDS; b++) {
        if (s_bar_height[b] >= s_peak_height[b]) {
            s_peak_height[b] = s_bar_height[b];
            s_peak_hold[b]   = 8; /* Hold peak for 8 ticks (~80 ms) */
        } else {
            if (s_peak_hold[b] > 0) {
                s_peak_hold[b]--;
            } else {
                if (s_peak_height[b] > 0) {
                    s_peak_height[b]--; /* Glides down 1 unit per tick */
                }
            }
        }
    }

    /* 4. Update Window UI if window is open and visible */
    if (s_player_win && (s_player_win->flags & WINDOW_FLAG_VISIBLE)) {
        player_redraw_dynamic(s_player_win);
    }
}
